import shutil
import openpyxl
from decimal import Decimal, ROUND_HALF_UP

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb.active
vws = vals[ws.title]

def to_decimal(value):
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    s = str(value).strip()
    try:
        return Decimal(s)
    except Exception:
        return None

for r in range(12, 16):
    numbers = []
    for row in range(11, r + 1):
        d = to_decimal(vws.cell(row=row, column=2).value)
        if d is not None:
            numbers.append(d)

    if numbers:
        avg = sum(numbers) / Decimal(len(numbers))
        result = float(avg.quantize(Decimal("0.001"), rounding=ROUND_HALF_UP))
        if result == 0:
            result = 0.0
    else:
        result = None

    ws.cell(row=r, column=2).value = result
    print(f"B{r} = {result}")

wb.save(OUT)
