import shutil
import openpyxl
from decimal import Decimal, ROUND_HALF_UP

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Blad1"
if sheet_name not in wb.sheetnames:
    sheet_name = wb.active.title

ws = wb[sheet_name]
vws = vals[sheet_name]

def to_decimal(value):
    if value is None:
        return Decimal(0)
    if isinstance(value, bool):
        return Decimal(1 if value else 0)
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    s = str(value).strip()
    if not s:
        return Decimal(0)
    try:
        return Decimal(s)
    except Exception:
        return Decimal(0)

start_row = 11
end_row = 15
data_col = 1

# Fallback only if the expected data column is empty.
if all(vws.cell(row=r, column=data_col).value is None for r in range(start_row, end_row + 1)):
    if any(vws.cell(row=r, column=2).value is not None for r in range(start_row, end_row + 1)):
        data_col = 2

cumulative = Decimal(0)

for r in range(start_row, end_row + 1):
    cumulative += to_decimal(vws.cell(row=r, column=data_col).value)

    if r >= 12:
        count = r - start_row + 1
        avg = cumulative / Decimal(count)
        rounded = avg.quantize(Decimal("0.001"), rounding=ROUND_HALF_UP)

        cell = ws.cell(row=r, column=2)
        cell.value = float(rounded)
        cell.number_format = "0.000"

        print(f"B{r} = {float(rounded)}")

wb.save(OUT)
